insert into sc_plans(id,line,status,title,title_ko,hook,emotion,korea,outline,spec,signal,publish_at,feedback) values ('P261031-kachi-handkerchief','emo','approved',$q$He saved a baby magpie years ago… 🐦❤️$q$,$q$오래전 봄비 오는 날, 소년이 둥지에서 떨어진 새끼 까치를 자기 빨간 손수건으로 감싸 하트 구멍 새집에 넣어 준다. 세월이 흘러 같은 마루, 아빠가 된 그 소년과 딸 앞에 까치가 감 하나를 물어다 놓는다. 까치 목에 빛바랜 빨간 손수건 — 그때 그 새끼였다. (까치 목수건의 기원)$q$,$q$첫 컷: 소년이 왜 새끼 새에게 자기 손수건을 감아 줄까? — 빨간 매듭이 마지막에 회수된다$q$,'kind',$q$시골 한옥 마루·감나무·소나무$q$,$q$[{"scene": "오래전 봄비, 한옥 마루. 소년이 빨간 손수건으로 감싼 새끼 까치를 하트 구멍 새집에 넣는다", "cap": "Years ago, he gave a fallen chick his red handkerchief."}, {"scene": "지금, 가을 오후. 같은 마루에 아빠가 된 소년과 다섯 살 딸. 처마 밑엔 낡은 하트 새집", "cap": "Many autumns later."}, {"scene": "까치가 딸 발치에 잘 익은 감 하나를 내려놓고 올려다본다. 까치 목에 빛바랜 빨간 매듭", "cap": "Then a magpie came with a gift."}, {"scene": "무릎 위 까치의 빨간 목수건을 알아본 아빠가 눈물 섞인 미소", "cap": "It still wore his handkerchief."}]$q$::jsonb,$q${"bible": {"boy": "BOY (years ago): a Korean boy about eight years old, round face, short straight black hair with a small cowlick, light-blue short-sleeved shirt, navy shorts.", "man": "MAN (now): the same Korean boy grown up into a man in his mid-thirties: same round face, short straight black hair with a small cowlick, oatmeal-beige knit cardigan over a white shirt.", "girl": "GIRL: his daughter about five years old, round face, two short black pigtails, pink knit cardigan.", "place": "PLACE: the wooden-floored porch (maru) of a small countryside hanok with a grey-tiled roof, a big old pine tree in the yard, and a small white-painted wooden birdhouse with a heart-shaped entrance hole hanging under the eave.", "kerchief": "the plain red cotton handkerchief tied in a small knot", "palette": "cut 1 = years ago: soft spring rain, cool green-grey light, slightly faded colors; cuts 2-4 = now: golden autumn late afternoon, a persimmon tree with orange fruit beside the pine"}, "details": [{"prop": "빨간 손수건 매듭 = 까치의 빨간 목수건", "where": [1, 3, 4], "meaning": "까치가 바로 그 새끼 — 채널 진행자 까치의 기원"}, {"prop": "하트 구멍 흰 새집(새것 → 낡음)", "where": [1, 2, 4], "meaning": "같은 집, 흐른 세월"}, {"prop": "까치가 가져온 감 하나", "where": [3], "meaning": "은혜를 갚는 좋은 소식의 새"}], "format": "kindness-returns (보은·되돌아온 친절) + 까치 기원", "hook_type": "why-question-first-frame", "music": "music_miss-you", "pinned": "Have you ever been remembered for a small kindness? ❤️ Tell Kachi", "description": "Years ago, a little boy wrapped a fallen baby magpie in his red handkerchief.\nMany autumns later, a magpie came back to his porch… still wearing it.\n\nIn Korea, the magpie is the bird that brings good news 🐦\n\n#Kindness #Magpie #Korea #Hanok #Wholesome #shorts", "tags": ["kindness", "magpie", "baby bird", "father and daughter", "hanok", "Korea", "miniature animation", "Kachi", "From Korea With Love"], "notes": "한 컷에 2명+까치 금지: 3컷 딸+까치, 4컷 아빠+까치. 소년→어른 얼굴 일관성은 kh1 을 ref. 손수건 매듭은 까치 기본 디자인(빨간 매듭 목수건)과 같은 모양으로.", "reuse": [], "followup_of": null, "est_usd": 1.5, "cuts": 4, "p0_scores": {"surprise": 5, "emotion": 4, "natural": 4, "kachi": 5}, "production": {"gen_img": "scripts/side/gen_next/M261031-handkerchief-img.json", "gen_vid": "scripts/side/gen_next/M261031-handkerchief-vid.json", "render_id": "E261031-handkerchief"}, "shots": []}$q$::jsonb,$q${"evidence": [{"title": "A Small Act of Kindness ❤️", "views": 9126965, "channel": "Fable Spark", "video_id": "RmoPM0qClEI"}]}$q$::jsonb,'2026-10-31T22:00:00+09:00',jsonb_build_array($q${"by": "claude", "type": "note", "text": "빈 칸(10/31 22:00) 새 기획 — 보은 구조(최근 하루 12만~900만 회 '작은 친절' 최상위)에 까치 목수건의 기원을 얹음. PLAN-FIRST 촬영표 완성(4컷·엔딩 포함 약 22초·예상 실비 $1.5: 그림 4·영상 4). P0 점수 놀라움 5·감정 4·자연스러움 4·까치 역할 5 → 승인. 생성 작업 파일: scripts/side/gen_next/M261031-handkerchief-img.json / -vid.json (제작 때 scripts/side/gen/ 로 옮겨 실행)."}$q$::jsonb || jsonb_build_object('at',now())))